<?php
declare(strict_types=1);
function student_shell_activity(?array $activity,?array $student): ?array {return $activity;}
function student_shell_navigation_items(): array {
    return [
        'home'=>['label'=>'Início','href'=>'/aluno/'],
        'courses'=>['label'=>'Cursos','href'=>'/aluno/cursos.php'],
        'notebook'=>['label'=>'Caderno','href'=>'/aluno/caderno.php'],
        'laboratory'=>['label'=>'Laboratório','href'=>'/aluno/ferramentas.php'],
    ];
}
function student_shell_active_area(string $path,array $query=[]): string {
    $route=basename($path);
    if(in_array($route,['perfil.php','senha.php'],true))return 'account';
    if(in_array($route,['caderno.php','teste.php','teste-etapa.php','teste-compartilhado.php','excluir-teste.php','comparar-processos.php','processamento-realizado.php','registro-roteiro.php'],true))return 'notebook';
    if(in_array($route,['cursos.php','duvidas.php'],true))return 'courses';
    if($route==='processar.php')return (int)($query['test']??0)>0?'notebook':'laboratory';
    if($route==='processamentos.php'&&(int)($query['test']??0)>0)return 'notebook';
    if(in_array($route,['ferramentas.php','reciprocidade.php','exposicao.php','temporizador.php','processamentos.php','processamentos-trocar.php','calibracao.php','preparo-solucoes.php','inventario.php','inventario-item.php','preparos.php'],true))return 'laboratory';
    return 'home';
}
function student_course_context_header(array $enrollment,string $active='overview',string $materialUrl=''): void {
    $cohortUuid=(string)($enrollment['cohort_uuid']??'');$overviewUrl='/aluno/cursos.php?cohort='.rawurlencode($cohortUuid);$questionsUrl='/aluno/duvidas.php?cohort='.rawurlencode($cohortUuid);$statusLabel=function_exists('student_enrollment_cohort_status_label')?student_enrollment_cohort_status_label((string)($enrollment['cohort_status']??'')):(string)($enrollment['cohort_status']??'');?>
    <header class="student-course-context" aria-label="Contexto do curso"><a class="student-course-context-back" href="/aluno/cursos.php">← Cursos</a><div class="student-course-context-head"><div><p class="student-course-context-kicker"><?=h((string)($enrollment['cohort_title']??''))?></p><h1 class="student-course-context-title"><?=h((string)($enrollment['course_title']??'Curso'))?></h1></div><?php if($statusLabel!==''):?><span class="student-status student-course-context-status"><?=h($statusLabel)?></span><?php endif;?></div><nav class="student-course-context-nav" aria-label="Navegação do curso"><a href="<?=h($overviewUrl)?>"<?=$active==='overview'?' aria-current="page"':''?>>Visão geral</a><?php if($materialUrl!==''):?><a href="<?=h($materialUrl)?>"<?=$active==='material'?' aria-current="page"':''?>>Material</a><?php endif;?><a href="<?=h($questionsUrl)?>"<?=$active==='questions'?' aria-current="page"':''?>>Dúvidas</a></nav></header><?php
}
function student_shell_nav(string $active,string $class): void {?>
<nav class="<?=h($class)?>" aria-label="Área do aluno"><?php foreach(student_shell_navigation_items() as $key=>$item):?><a href="<?=h((string)$item['href'])?>"<?=$active===$key?' aria-current="page"':''?>><?=h((string)$item['label'])?></a><?php endforeach;?></nav><?php
}
function student_shell_toolbox(array $student): void {
    $toolKeys=[];foreach(student_tools_for_student(database(),(int)$student['id']) as $tool)$toolKeys[(string)$tool['tool_key']]=true;?>
