      <div class="student-toolbox-head"><div><p class="student-kicker">Acesso rápido</p><h2 id="student-toolbox-title">Ferramentas</h2></div><button class="button button-secondary button-compact" type="button" data-toolbox-close>Fechar</button></div>
      <div class="student-toolbox-body">
        <?php if(isset($toolKeys['reciprocity'])):?><section class="student-toolbox-tool" data-quick-reciprocity><h3>Reciprocidade</h3><div class="student-form-grid"><label class="form-field">Tempo sem reciprocidade<input data-quick-reciprocity-source placeholder="4 s, 02:30 ou 00:00:04"></label><label class="form-field">Tempo com reciprocidade<input data-quick-reciprocity-target readonly></label></div></section><?php endif;?>
        <?php if(isset($toolKeys['exposure'])):?><section class="student-toolbox-tool" data-exposure-tool><h3>Exposição equivalente</h3><div class="student-form-grid"><label class="form-field">Tempo inicial<input type="number" min="0" step="0.001" value="1" data-exposure-time></label><label class="form-field">Abertura inicial<input type="number" min="0.1" step="0.1" value="8" data-exposure-f-start></label><label class="form-field">EI inicial<input type="number" min="1" step="1" value="100" data-exposure-ei-start></label><label class="form-field">Abertura desejada<input type="number" min="0.1" step="0.1" value="8" data-exposure-f-target></label><label class="form-field">EI desejado<input type="number" min="1" step="1" value="100" data-exposure-ei-target></label><label class="form-field">Compensação (EV)<input type="number" step="0.1" value="0" data-exposure-ev></label></div><div class="student-tool-result"><span>Tempo equivalente</span><strong data-exposure-result>1 s</strong><small data-exposure-reciprocity></small></div></section><?php endif;?>
        <?php if(isset($toolKeys['lab_timer'])):?><section class="student-toolbox-tool"><h3>Processamentos</h3><p>Monte roteiros com várias etapas e execute-os no modo laboratório.</p><a class="button button-primary button-compact" href="/aluno/processamentos.php">Abrir processamentos</a></section><?php endif;?>
        <div class="student-toolbox-links"><?php if(isset($toolKeys['lab_timer'])):?><a href="/aluno/processamentos.php"><span>Processamentos</span><span>→</span></a><?php endif;?><?php if(isset($toolKeys['solution_prep'])):?><a href="/aluno/ferramentas.php#receitas"><span>Receitas e preparo</span><span>→</span></a><?php endif;?><a href="/aluno/inventario.php"><span>Inventário</span><span>→</span></a><a href="/aluno/preparos.php"><span>Predefinições de revelação</span><span>→</span></a><a href="/aluno/calibracao.php"><span>Referências de calibração</span><span>→</span></a><a href="/aluno/ferramentas.php"><span>Ver bancada completa</span><span>→</span></a></div>
      </div>
    </dialog><?php
}
