    $assetVersion=function_exists('admin_asset_version')?admin_asset_version():(string)(@filemtime(dirname(__DIR__).'/assets/ui-core.css')?:1);$resolvedActivity=student_shell_activity($activity,$student);$design=$resolvedActivity?cms_design_settings(database(),(int)$resolvedActivity['id'],PUBLIC_LOCALE_PT_BR):cms_design_defaults();$path=(string)parse_url((string)($_SERVER['REQUEST_URI']??'/aluno/'),PHP_URL_PATH);$active=student_shell_active_area($path,$_GET);$brand=function_exists('installation_brand_name')?installation_brand_name():'JSaidler Fotografia';$processFeature=str_contains($path,'/aluno/processamentos.php')||str_contains($path,'/aluno/processamentos-trocar.php')||str_contains($path,'/aluno/processar.php')||str_contains($path,'/aluno/registro-roteiro.php');$notebookFeature=str_contains($path,'/aluno/caderno.php')||str_contains($path,'/aluno/teste.php')||str_contains($path,'/aluno/teste-etapa.php')||str_contains($path,'/aluno/processamento-realizado.php')||str_contains($path,'/aluno/comparar-processos.php');$recordingFeature=str_contains($path,'/aluno/processamento-realizado.php');$stockFeature=str_contains($path,'/aluno/inventario')||str_contains($path,'/aluno/preparos.php');?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow,noarchive,nosnippet"><meta name="theme-color" content="<?=h((string)($design['colors']['bg']??'#f2f2ef'))?>"><style data-cms-design-fonts><?=cms_design_font_import_css($design)?></style><link rel="stylesheet" href="/template/page.css?v=<?=h($assetVersion)?>"><style data-cms-design-tokens><?=cms_design_css($design)?></style><link rel="stylesheet" href="/assets/ui-core.css?v=<?=h($assetVersion)?>"><link rel="stylesheet" href="/assets/student-area.css?v=<?=h($assetVersion)?>"><link rel="stylesheet" href="/assets/student-workbench.css?v=<?=h($assetVersion)?>"><link rel="stylesheet" href="/assets/st